export interface ApiContainersUpdateRequest {
  /**
   * Human-readable name for the container - must be unique within the project
   * @minLength 1
   * @maxLength 100
   */
  name?: string;
  /**
   * HEX color for the container (e.g., #FF0000 or FF0000). If not provided, a random color will be generated. The # prefix will be added automatically if missing, and the color will be converted to uppercase.
   * @pattern ^#[0-9A-Fa-f]{3}$|^#[0-9A-Fa-f]{6}$|^[0-9A-Fa-f]{3}$|^[0-9A-Fa-f]{6}$
   */
  color?: string;
  /** Whether AI features are enabled. If omitted, the current value is preserved. */
  ai?: boolean;
  /** Whether the container starts automatically on host boot. If omitted, the current value is preserved. */
  autostart?: boolean;
  /** Sharing scope for /ramdisk. `container` (default) mounts only private storage. `project` additionally mounts /ramdisk/project, shared with your other containers in this project ON THE SAME SERVER (a RAM disk cannot span servers). Refused when the project has other members. */
  ramdisk_scope?: "container" | "project";
  /** Whether to mount a ramdisk at /ramdisk. If omitted, the current value is preserved. Backed by a shared per-server memory pool (512 MiB by default, never more than 50% of the server memory) shared with your other containers on that server. Data survives container restarts but is LOST on a host reboot — which is why it suits secrets and scratch data that must not persist to disk. It is RAM, so it counts against memory rather than disk. */
  ramdisk?: boolean;
  /** Environment variables to set in the container as key-value pairs. Keys must match `^[a-zA-Z_][a-zA-Z0-9_]*$` and be at most 128 characters long. */
  environment_vars?: Record<string, string>;
  /** SSH public key for direct SSH access to this container. Keys are globally unique - one container per key; re-sending the same key for the same container is a no-op (and completes an earlier change that did not finish). Set to null to REMOVE the key: direct SSH stops accepting it within about a minute, an already-open session is closed shortly after, and the key becomes installable again afterwards. An empty or whitespace-only string is rejected with 400 (send null to remove). Requires a token with the ssh-keys resource permission to set or replace; removal needs only container update permission. */
  ssh_public_key?: string | null;
  /**
   * Optional comment for the container (max 16000 characters). Set to null to clear existing comment.
   * @maxLength 16000
   */
  comment?: string | null;
  /** Update realm membership for this container. Containers can have different realm membership than their parent project. A signed-in session (JWT) or an auth token without realm restrictions can modify realm_ids; realm-restricted tokens cannot change realm membership. */
  realm_ids?: string[];
}

