export interface ApiContainersCopyRequest {
  /**
   * ID of the project where the copy will be created
   * @pattern ^[0-9a-f]{24}$
   */
  target_project_id: string;
  /**
   * ID of the server where the copy will be created (defaults to source server)
   * @pattern ^[0-9a-f]{24}$
   */
  target_server_id?: string;
  /**
   * Name for the copied container (auto-generated if not provided)
   * @minLength 3
   * @maxLength 100
   * @pattern ^[a-zA-Z0-9-_]+$
   */
  name?: string;
  /** SSH public key for the copied container (must be unique, not inherited from source) */
  ssh_public_key?: string | null;
  /**
   * Specific snapshot to copy from (copies latest state if not provided). An auth token needs `containers.features.snapshots` to use it.
   * @pattern ^[a-zA-Z0-9-_]+$
   */
  source_snapshot?: string;
  /** Whether to copy firewall rules from source container to target container */
  copy_firewall_rules?: boolean;
  /** Whether to copy network rules/settings from source container to target container */
  copy_network_rules?: boolean;
  /** Grant the COPY /dev/kvm passthrough (run full VMs). The copy NEVER inherits the source's KVM grant, so this decides KVM for the copy independently, on the TARGET server. Available on rented / dedicated (bare-metal) targets ONLY (never free tier); rejected (403) otherwise. Defaults to false. */
  kvm?: boolean;
  /** Accepted alias of `kvm` on input (`kvm` wins if both are sent and they must agree). */
  dev_kvm?: boolean;
}

