export interface AgentWorkflowsSetRequest {
  /** The full workflow definition object (steps, entry_point, summary). Validated strictly by the agent before an atomic write. */
  definition: Record<string, unknown>;
  /** Optional optimistic-concurrency guard: the 'revision:' value from getWorkflow (?include_revision=true). If the stored workflow changed since that read, the upsert is refused with [revision_conflict] and nothing is written. Omit to save unconditionally. The revision is bound to the realm this request resolves to: on a gateway without a realm pin, a revision read while another realm was active is refused [revision_conflict] (current_revision is this realm's), never written into the other realm. */
  expected_revision?: string;
  /** Optional create-only guard: refuse with [already_exists] (writing nothing) if any workflow with this name already exists. Use when creating a new workflow that must not overwrite an existing one. Mutually exclusive with expected_revision. */
  expected_absent?: boolean;
}

/**
 * The tool envelope. On a CAS refusal (expected_revision/expected_absent failed) output is bracket-tagged ([revision_conflict] / [already_exists]) and the additive code/current_revision keys are present.
 */
export interface AgentWorkflowsSetResponse {
  statusCode: number;
  message: string;
  data: { status?: string; output?: string; is_error?: boolean; code?: "revision_conflict" | "already_exists"; current_revision?: string };
}

