export interface User {
  /**
   * Unique user identifier
   * @pattern ^[0-9a-f]{24}$
   */
  id: string;
  /**
   * Unique username (alphanumeric + underscores + hyphens)
   * @pattern ^[a-zA-Z0-9_-]+$
   */
  username: string;
  /** User email address */
  email?: string;
  /** Display name (can differ from username) */
  alias: string;
  /**
   * ED25519 public key (64 hexadecimal characters)
   * @pattern ^[0-9a-fA-F]{64}$
   */
  public_key?: string;
  /** Custom metadata object for storing additional user information */
  metadata?: Record<string, unknown>;
  /** Account ban status. Banned users cannot access the API. */
  is_banned: boolean;
  /** Whether the user has verified their email address */
  email_verified?: boolean;
  /** Avatar image URL from OAuth provider */
  avatar_url?: string | null;
  /** How the user signed up, for example email, github or google */
  signup_method?: string | null;
  /** Beta gate: whether this account may claim a free-tier server while an invite is required for free-tier access. Always true (or irrelevant) when no invite is required. */
  free_tier_unlocked?: boolean;
  /** When the account was unlocked for free-tier claiming. */
  free_tier_unlocked_at?: string | null;
  /** How free-tier access was enabled for this account, for example invite_code. Null while it is not enabled. */
  free_tier_unlock_source?: string | null;
  /** Per-account onboarding/UI milestones: key -> ISO timestamp (presence = done). */
  onboarding?: Record<string, unknown>;
  /** ISO 8601 account creation timestamp */
  created_at: string;
  /** ISO 8601 last modification timestamp */
  updated_at: string;
}

export interface Project {
  /**
   * Unique project identifier
   * @pattern ^[0-9a-f]{24}$
   */
  id: string;
  /**
   * Owner user ID
   * @pattern ^[0-9a-f]{24}$
   */
  user_id: string;
  /**
   * Human-readable project name. Must be unique per user.
   * @minLength 1
   * @maxLength 100
   */
  alias: string;
  /**
   * HEX color code for visual organization (auto-normalized to uppercase with # prefix)
   * @pattern ^#[0-9A-F]{3,6}$
   */
  color: string;
  /** ISO 8601 creation timestamp */
  created_at: string;
  /** ISO 8601 last modification timestamp */
  updated_at: string;
  /**
   * Maximum containers quota for this project. Null = unlimited.
   * @minimum 0
   */
  max_containers?: number /* min: 0 */ | null;
}

export interface ProjectWithPermissions {
  /**
   * Unique project identifier
   * @pattern ^[0-9a-f]{24}$
   */
  id: string;
  /**
   * Owner user ID
   * @pattern ^[0-9a-f]{24}$
   */
  user_id: string;
  /**
   * Human-readable project name. Must be unique per user.
   * @minLength 1
   * @maxLength 100
   */
  alias: string;
  /**
   * HEX color code for visual organization (auto-normalized to uppercase with # prefix)
   * @pattern ^#[0-9A-F]{3,6}$
   */
  color: string;
  /** ISO 8601 creation timestamp */
  created_at: string;
  /** ISO 8601 last modification timestamp */
  updated_at: string;
  /**
   * Maximum containers quota for this project. Null = unlimited.
   * @minimum 0
   */
  max_containers?: number /* min: 0 */ | null;
  /** True if this is the user's auto-provisioned default project. Exactly one project per user has this flag after signup. */
  is_default?: boolean;
  /** Realm IDs this project belongs to. Projects can belong to multiple realms for multi-tenant isolation. */
  realm_ids?: string[];
  /** List of users with access to this project (only included when include_permissions=true) */
  permissions?: ProjectPermission[];
}

