export interface WaitUntilBody {
  /** `window-present` waits for at least one window to match `pattern`.
`window-absent` waits for the last match to go away, or for a
specific `windowId` to stop existing. */
  condition: "window-present" | "window-absent";
  /**
   * Extended POSIX regex. Required for
`window-present`; for `window-absent` give either this or
`windowId`, not both. A pattern that does not compile is a 400,
not an empty result, and so is one containing a NUL (it could never
reach the subprocess).
   * @minLength 1
   * @maxLength 512
   * @pattern ^[^\u0000]+$
   */
  pattern?: string;
  /** Which window property `pattern` is matched against. `name` is the
title, which changes while an application runs; `class` is stable
across a window's life and is the better choice for "has the app
started yet". */
  match?: "name" | "class" | "classname";
  /** Restrict the search to windows the X server reports as viewable
This is not a way to skip minimized windows: a window stays viewable
after `window/minimize`, even once the display's window manager
reports it iconic. What it does filter is unmapped
windows, which on a seamless session means every window while no
viewer is attached.

Sending it alongside `windowId` is rejected: that is an identity
check, not a search, so the flag would be silently ignored. The
same goes for `match`. */
  onlyVisible?: boolean;
  /** Wait for this exact window to stop existing. `window-absent` only,
and not together with `pattern`, `match` or `onlyVisible`. */
  windowId?: number /* min: 0, max: 4294967295 */ | string;
  /**
   * @minimum 100
   * @maximum 25000
   */
  timeoutMs?: number /* min: 100, max: 25000 */;
  /**
   * Gap between observations. An explicit value above `timeoutMs` is
rejected; the default is not, so a `timeoutMs` under 250 is a legal
request for a single look rather than an error.
   * @minimum 100
   * @maximum 5000
   */
  pollMs?: number /* min: 100, max: 5000 */;
}

export interface WaitUntilResult {
  /** Whether the condition held before the timeout. */
  success: boolean;
  condition: "window-present" | "window-absent";
  waitedMs: number;
  /** Observations that completed. An observation that was aborted, or
killed before it could answer, is not counted — so `polls: 0` with
`timedOut: true` means the condition was never actually observed. */
  polls: number;
  /** Present and true when the timeout expired with the condition unmet. */
  timedOut?: boolean;
  /** Window ids that matched, for a satisfied `window-present`. Empty
for a `windowId` check and for `window-absent`. */
  windows?: number[];
}

