/**
 * VFS settings to change. Each field you send replaces the mount's current value, and fields you omit keep it. Send at least one field.
 */
export interface VfsConfigPatch {
  /** Accepted only as false, so a GET response can be sent back unchanged. It cannot be set. */
  allow_non_empty?: false;
  /** Accepted only as false, so a GET response can be sent back unchanged. It cannot be set. */
  allow_other?: false;
  /** How long an unused file stays in the local cache. Seconds as a whole number, or a string such as "30s", "5m" or "1h30m" (units h, m and s; a number without a unit is seconds). Between 0 and 2592000 seconds (30 days). Default for new mounts: 1h. */
  cache_max_age?: string | number /* min: 0, max: 2592000 */;
  /** Maximum size of the local cache. Bytes as a whole number, or a string such as "10G" or "128M" (K, M, G and T are powers of 1024, with an optional trailing B; a string without a unit is bytes). 0 means no limit; otherwise between 1M (1048576) and 9007199254740991 bytes. Default for new mounts: 10G. */
  cache_max_size?: string | 0 | number /* min: 1048576, max: 9007199254740991 */;
  /** How file contents are cached locally: off (no cache; a file cannot be opened for reading and writing at once), minimal, writes (files opened for writing), or full. Default for new mounts: writes. */
  cache_mode?: "off" | "minimal" | "writes" | "full";
  /** How long connecting to the backend may take before the attempt fails (1 minute when not set). Seconds as a whole number, or a string such as "30s", "5m" or "1h30m" (units h, m and s; a number without a unit is seconds). Between 1 and 120 seconds (2m). */
  contimeout?: string | number /* min: 1, max: 120 */;
  /** How long directory listings are cached. Seconds as a whole number, or a string such as "30s", "5m" or "1h30m" (units h, m and s; a number without a unit is seconds). Between 0 and 2592000 seconds (30 days). Default for new mounts: 5m. */
  dir_cache_time?: string | number /* min: 0, max: 2592000 */;
  /**
   * How many times one failed request to the backend is retried before the operation fails: a whole number between 0 and 10. Not set for new mounts: 10 retries.
   * @minimum 0
   * @maximum 10
   */
  low_level_retries?: number /* min: 0, max: 10 */;
  /** How often the backend is checked for changes, on backends that support it; 0 turns checking off. Seconds as a whole number, or a string such as "30s", "5m" or "1h30m" (units h, m and s; a number without a unit is seconds). Between 0 and 2592000 seconds (30 days). Default for new mounts: 1m. */
  poll_interval?: string | number /* min: 0, max: 2592000 */;
  /** Size of each read from the backend. Bytes as a whole number, or a string such as "10G" or "128M" (K, M, G and T are powers of 1024, with an optional trailing B; a string without a unit is bytes). Between 1M (1048576) and 1G (1073741824) bytes. Default for new mounts: 128M. */
  read_chunk_size?: string | number /* min: 1048576, max: 1073741824 */;
  /** Refuse writes through the mount path. The backend file API can still write. Default for new mounts: false. */
  read_only?: boolean;
  /** How long a transfer with the backend may stay idle before it fails. A lower value makes reads and uploads fail sooner when the backend stops answering (5 minutes when not set). Seconds as a whole number, or a string such as "30s", "5m" or "1h30m" (units h, m and s; a number without a unit is seconds). Between 1 and 600 seconds (10m). */
  timeout?: string | number /* min: 1, max: 600 */;
  /** Upload delay: how long a file written and closed waits before it is uploaded. Seconds as a whole number, or a string such as "30s", "5m" or "1h30m" (units h, m and s; a number without a unit is seconds). Between 0 and 3600 seconds (1h). Default for new mounts: 5s. */
  write_back?: string | number /* min: 0, max: 3600 */;
}

export interface Mount {
  /** Saved with the mount. It currently has no effect: files kept on the server are not uploaded, whatever its value. Changing it does not restart the mount. Default for new mounts: true. */
  auto_deliver: boolean;
  /** Backend ID this mount belongs to */
  backend_id: string;
  /** Unix timestamp of mount creation */
  created_at: number;
  /** Reserved; not currently present. */
  delivery?: { pending_upload_id: string; stop: string };
  /** Why the mount is not serving. Absent when there is no error. */
  error?: string;
  /**
   * Mount ID (e.g., mount_550e8400e29b41d4a716446655440000)
   * @pattern ^mount_[0-9a-f]{32}$
   */
  id: string;
  /** Human-readable label for this mount. Absent when it has none. */
  label?: string;
  metrics: { bytes_read: number; bytes_written: number; cache_hits: number; cache_misses: number; files_accessed: number; last_accessed: number };
  /** Absolute filesystem path where the mount is accessible. Use this path to read and write files on the mounted backend. */
  mount_path: string;
  pending_uploads: PendingUploadsSummary;
  /** mounting: not serving yet. active: serving. error: not serving; see error. unmounting and unmounted: being removed. */
  status: "mounting" | "active" | "error" | "unmounting" | "unmounted";
  /** What the mount is waiting for, or how many of its files are kept on the server and not uploaded, and why. Absent when there is nothing to say. */
  status_message?: string;
  /** Unix timestamp of the last change to this mount */
  updated_at: number;
  uploads?: MountUploads;
  vfs_config: VfsConfig;
}

/**
 * With `uploads=wait` or `uploads=discard` only: what became of what was written on the removed mount, or the removed backend's mounts, and not uploaded yet. Absent with `uploads=keep`.
 */
export interface MountDeleteUploads {
  /** true: nothing is held open and nothing is left to upload. false: with `wait`, the deadline passed first, or the uploads had already stopped with something left (that is then kept on the server and is not uploaded); with `discard`, always. */
  delivered: boolean;
  /**
   * With `wait`, when delivered is false: files written and not uploaded yet. null when that could not be seen in full: a stored record that cannot be read leaves every wait unsure until it is deleted (GET /api/v1/pending-uploads/unreadable).
   * @minimum 0
   */
  dirty?: number /* min: 0 */ | null;
  /**
   * With `discard`: files deleted without being uploaded. null when that could not be counted, or a stop could not be confirmed; the uploads of that part then go on as with `keep`. A backend DELETE that answers null keeps the backend: repeat it to delete what is left. When repeats stay null, a stored record that cannot be read may be the cause: GET /api/v1/pending-uploads/unreadable lists it.
   * @minimum 0
   */
  discarded?: number /* min: 0 */ | null;
  /**
   * With `wait`, when delivered is false: files and folders still held open on the mount. null when that could not be seen in full.
   * @minimum 0
   */
  open_handles?: number /* min: 0 */ | null;
}

/**
 * A stored record of unsent files that cannot be read, so what it holds is unknown. While one exists, a mount or backend DELETE with `uploads=wait` or `uploads=discard` cannot confirm that nothing was left unsent.
 */
export interface UnreadablePendingUpload {
  /**
   * The record's ID
   * @pattern ^[0-9a-f]{32}$
   */
  id: string;
  /** unreadable: it could not be read. damaged: it was read, and is cut short, damaged, or not one this server wrote. */
  reason: "unreadable" | "damaged";
  /**
   * The record's size in bytes. Absent when it cannot be seen.
   * @minimum 0
   */
  size?: number /* min: 0 */;
}

export interface PendingUploadFile {
  /** Whether the held copy is known to be whole. Only complete files can be delivered. An incomplete file can be downloaded, with any missing ranges read as zeros, or discarded. */
  complete: boolean;
  /** Unix timestamp of the held copy's last change */
  modified_at: number;
  /** The path relative to the backend root, present only when its bytes are valid UTF-8; exactly those bytes. */
  path?: string;
  /**
   * The file's identifier: its path relative to the backend root, as raw bytes in base64url without padding. Every file has one; it is the only way to name a file whose name is not valid UTF-8.
   * @pattern ^[A-Za-z0-9_-]+$
   */
  path_b64: string;
  /** Present when path is absent: the path with each byte that is not valid UTF-8 shown as U+FFFD. For display only; no request accepts it, and it can look the same as another file's path. */
  path_display?: string;
  /** open_when_stopped: the file was open when its mount stopped and may be incomplete. unconfirmed_at_stop: its mount stopped unexpectedly, so whether the file was complete is not known. metadata_unreadable: its cache record is damaged; download or discard it, it cannot be delivered. upload_failing: its upload kept failing. stopped_by_request: its upload was stopped on request before the file was sent. changed_on_storage: the file changed on the storage since it was cached; deliver or download it to choose. check_failed: the storage could not be checked, so whether the file changed there is not known. cannot_verify: the storage cannot show whether this file changed since it was cached; deliver or download it to choose. */
  reason: "open_when_stopped" | "unconfirmed_at_stop" | "metadata_unreadable" | "upload_failing" | "stopped_by_request" | "changed_on_storage" | "check_failed" | "cannot_verify";
  /**
   * Bytes
   * @minimum 0
   */
  size: number /* min: 0 */;
}

/**
 * Unsent upload data of one mount session: files still uploading on their own (state uploading), or held back because they may be incomplete or out of date. The files are listed by GET /api/v1/pending-uploads/{id}/files.
 */
export interface PendingUpload {
  /** The backend the files belong to. Absent when that backend no longer exists; the files can still be delivered to another backend with backend_id, downloaded or discarded. */
  backend_id?: string;
  /** Whether a delivery with the item's saved connection settings can start now. false when those settings are no longer accepted, or may be any of several backends' (unsettled_backend_ids), so deliver with backend_id instead; when no held file is complete, or while the item is uploading or delivering. An item whose backend was removed still delivers with its saved settings. */
  deliverable: boolean;
  /**
   * Number of files
   * @minimum 0
   */
  file_count: number /* min: 0 */;
  /** Pending upload ID */
  id: string;
  /**
   * Number of files with complete: false, which can only be downloaded or discarded
   * @minimum 0
   */
  incomplete_count: number /* min: 0 */;
  /** Why the last delivery ended early, for example not enough disk space to prepare the upload, or uploads that kept failing. Absent when there is none. */
  last_error?: string;
  /** The mount the files were written through. Absent when they do not belong to one mount, or the mount no longer exists. */
  mount_id?: string;
  /** Present when the item's last state change could not be saved yet. It is retried every minute and before any action on the item; discard still works. Absent otherwise. */
  needs_reconcile?: true;
  /** How many files have each reason; see PendingUploadFile.reason */
  reasons: { cannot_verify: number /* min: 0 */; changed_on_storage: number /* min: 0 */; check_failed: number /* min: 0 */; metadata_unreadable: number /* min: 0 */; open_when_stopped: number /* min: 0 */; stopped_by_request: number /* min: 0 */; unconfirmed_at_stop: number /* min: 0 */; upload_failing: number /* min: 0 */ };
  /** Unix timestamp since which the item has been in its current state */
  since: number;
  /** uploading: the files are still being uploaded on their own, by uploads that kept running through a service restart or that belong to a mount that was removed or changed, or files are still open on such a mount; stop turns them into a pending item. pending: held, waiting for the caller. delivering: a delivery is running; files leave the item as each one lands, and stop ends it. */
  state: "uploading" | "pending" | "delivering";
  /**
   * Bytes held, over every file
   * @minimum 0
   */
  total_bytes: number /* min: 0 */;
  /**
   * Programs that may be using the item's mount and could not be inspected, so its earlier settings cannot be retired: end those programs, or stop the item. Absent when there are none.
   * @minItems 1
   */
  unknown_holders?: { comm: string; pid: number /* min: 1 */ }[];
  /**
   * Present when a switch of the item's saved connection settings to another backend was cut short by a restart or an error: the backends whose settings they may now be. That is why a delivery without backend_id is refused (409, deliverable is false) until a delivery with backend_id installs that backend's settings. A running delivery is stopped by deleting the backend it uploads to with uploads=discard. Absent otherwise.
   * @minItems 1
   */
  unsettled_backend_ids?: string[];
}

