export interface NotifyRequest {
  /**
   * Notification body. Up to NOTIFY_SEND_MAX_BODY_LENGTH characters (default 1000); longer is rejected with 400, never truncated. No NUL byte; must not be only control characters.
   * @maxLength 1000
   */
  body?: string;
  /**
   * Notification category, at most 50 characters. Rejected when it contains a NUL byte or is empty once control characters are removed.
   * @maxLength 50
   */
  category?: string;
  /**
   * Target display, `"1"` or `":1"`, from 1 to 40000. Display 0 in any spelling (`0`, `:0`, `00`) and numbers above 40000 are rejected with 400. At most 5 digits; leading zeros are allowed (`"0001"` is display 1).
   * @pattern ^:?(?:[1-9][0-9]{0,3}|0[1-9][0-9]{0,3}|00[1-9][0-9]{0,2}|000[1-9][0-9]?|0000[1-9]|[1-3][0-9]{4}|40000)$
   */
  display: string;
  /**
   * Expiry timeout in milliseconds, 0-300000 (0 = never expires). Sent as notify-send `-t`.
   * @minimum 0
   * @maximum 300000
   */
  expire_time?: number /* min: 0, max: 300000 */;
  /**
   * Icon name or path, at most 1024 characters. No NUL byte.
   * @maxLength 1024
   */
  icon?: string;
  /**
   * Notification title. 1 to NOTIFY_SEND_MAX_SUMMARY_LENGTH characters (default 200); longer is rejected, never truncated. Must contain something other than control characters and no NUL byte.
   * @minLength 1
   * @maxLength 200
   */
  summary: string;
  /** Notification urgency level (lower-case on input; history reports it upper-cased) */
  urgency?: "low" | "normal" | "critical";
}

/**
 * A desktop notification read from the notification history. Unrecognised fields in the source record are passed through unchanged.
 */
export interface Notification {
  /** Notification ID. IDs are assigned per display, so the same ID can appear on two displays; identify a notification by `display_id` plus `id`. */
  id: number;
  /** Display the notification was shown on. Written by the desktop notification daemon, so it can be a number (`1`) or a string (`"1"` or `":1"`). Omitted when the source record has none. */
  display_id?: number | string;
  /** Name of the application that triggered the notification */
  appname: string;
  /** Notification summary/title */
  summary: string;
  /** Notification body text */
  body: string;
  /** Combined message text */
  message: string;
  /** Relative URL to the notification icon */
  icon_url?: string;
  /** Whether the notification has an icon */
  has_icon: boolean;
  /** Unix timestamp in milliseconds when the notification was created */
  timestamp: number;
  /** Expiry timeout the notification was sent with, in milliseconds. `-1` means the notification server's default, `0` means it never expires. `0` when the source record has none. */
  timeout: number;
  /** Progress value (0-100) for progress notifications, `0` when not set */
  progress: number;
  /** Notification category */
  category: string;
  /** Urgency level, upper-cased as stored by the notification daemon. `NORMAL` when the source record has none. */
  urgency: "LOW" | "NORMAL" | "CRITICAL";
  /** Stacking tag the sender set to replace an earlier notification in place, when set */
  stack_tag?: string;
  /** Key of the default action, when the notification has one */
  default_action_key?: string;
  /** Action buttons attached to the notification */
  actions?: NotificationAction[];
}

