/**
 * One snapshot of a pipe name, from `GET /{path}?status`. Every key is always present; `null` where it does not apply.
 */
export interface PipeStatus {
  state: "idle" | "waiting" | "streaming" | "complete" | "failed";
  /** `null` when idle, `pipe` for an HTTP transfer, `ws` for a WebSocket pair (`?ws`), `live` for a live stream */
  kind: "pipe" | "ws" | "live" | null;
  /** `ws`: peers connected now (0-2; 0 once the pair ended). `null` for pipes */
  peers: number | null;
  /** A generated UUID set once the transfer starts streaming, or the sender's own `transfer` id from its arrival; equals the receivers' `X-Hoody-Pipe-Transfer-Id` */
  transferId: string | null;
  /** `null` for a `ws` pair */
  hasSender: boolean | null;
  /** Receivers connected now (`live`: viewers). `null` for a `ws` pair */
  activeReceivers: number | null;
  /** The receiver count `n` the transfer waits for. `null` for a `ws` pair and for `live` */
  totalReceivers: number | null;
  bytesTransferred: number;
  /** The sender's Content-Length when known */
  totalBytes: number | null;
  /** Bytes per second, averaged since streaming started (frozen at the end) */
  speed: number;
  /** Seconds left while streaming with a known size */
  eta: number | null;
  /** Seconds since streaming started (frozen at the end) */
  elapsed: number;
  /** Why a failed transfer failed */
  reason: string | null;
  /** SHA-256 of the forwarded bytes, on a complete `?sha256` transfer */
  sha256: string | null;
}

