  /** Upstream scheme. Absent when there is no parsed upstream configuration to report */
  scheme?: "socks5" | "socks5h" | "http" | "https";
  /** Upstream host. Absent when there is no parsed upstream configuration to report */
  host?: string;
  /** Upstream port. Absent when there is no parsed upstream configuration to report */
