/**
 * Element target for /action and /wait. Exactly ONE of ref, selector, role, label, text, placeholder, testId must be set (400 otherwise). `name` only with role; `snapshotId` required with ref; `exact` only with role/label/text/placeholder (default true). Every target is strict: more than one match → 409 AMBIGUOUS_TARGET. Semantic and CSS targets address the top document only; use a ref to act inside an iframe. Refs are opaque tokens: a prefix like `f2` is Playwright's frame-sequence namespace and says nothing about iframes — pass refs back verbatim.
 */
export interface Target {
  /**
   * Element reference from the latest /snapshot of this tab (e.g. "e12"). Requires snapshotId.
   * @pattern ^(f\d+)?e\d+$
   */
  ref?: string;
  /** The snapshotId the ref came from. Must be the tab's latest and no main-frame navigation may have happened since (409 STALE_SNAPSHOT otherwise). */
  snapshotId?: string;
  /** A single CSS selector (forced through Playwright's css engine; ">>" chaining and other engines are rejected with 400). */
  selector?: string;
  /** ARIA role (Playwright's closed role list; unknown → 400). Combine with name. */
  role?: string;
  /** Accessible name, only with role. */
  name?: string;
  /** Form control by its label text. */
  label?: string;
  /** Element by its text content. */
  text?: string;
  /** Input by its placeholder. */
  placeholder?: string;
  /** Element by data-testid. */
  testId?: string;
  /** Exact (true) or substring, case-insensitive (false) matching for role/label/text/placeholder. */
  exact?: boolean;
}

