export interface BindingInfo {
  /** PULL only: the loopback address this listener bound. Two PULL bindings
on different 127/8 addresses can legitimately hold the same port, so
without this the rows are indistinguishable by anything but bind id and
give no way to reach either socket. Omitted for EXPOSE, which binds
`0.0.0.0`. */
  bindAddr?: string | null;
  /** @minimum 0 */
  bindId: number /* min: 0 */;
  /** @minimum 0 */
  containerPort: number /* min: 0 */;
  kind: string;
  mode: string;
}

export interface TunnelBindingView {
  /** PULL only: the loopback address this listener bound. Two PULL bindings
on different 127/8 addresses can legitimately hold the same port, so a
port alone no longer identifies the socket. Omitted for EXPOSE, which
binds `0.0.0.0`. */
  bindAddr?: string | null;
  /** @minimum 0 */
  bindId: number /* min: 0 */;
  /** @minimum 0 */
  containerPort: number /* min: 0 */;
}

/**
 * Batch item mode.
 */
export type BatchMode = "search" | "run";

/**
 * Full selector (search/run request) combining query filters, pick mode,
execution context, and output control fields. Can be expressed via query
parameters, path segments, or JSON body.
 */
export interface Selector {
  /** Primary name query (aliases q, name) */
  app: string;
  os?: Os;
  kind?: AppKind;
  /** Source kind filter (repeatable). Empty means no filter. */
  source?: SourceKind[];
  arch?: Arch;
  /** Free-form selector tags. Accepted and passed through to sources and recipe templates; they do not filter or rank candidates */
  tags?: string[];
  /** Named profile for default preferences */
  profile?: string;
  /** Release channel hint (e.g. stable, beta, nightly) */
  channel?: string;
  /** Exact version or constraint (provider-defined) */
  version?: string;
  /** Provider-defined variant (e.g. portable, headless) */
  variant?: string;
  /** Publisher hint for curated registries */
  publisher?: string;
  /** Repository hint (e.g. owner/name for GitHub sources) */
  repo?: string;
  /** Release hint (e.g. tag for release-based sources) */
  release?: string;
  /** Desired asset name or pattern */
  asset?: string;
  pick?: PickMode;
  /**
   * Candidate index (required when pick=index)
   * @minimum 0
   */
  pick_index?: number /* min: 0 */;
  /** Specific candidate ID (required when pick=id) */
  candidate_id?: string;
  /** Bind pick to a specific candidate set to avoid races */
  set_id?: string;
  /**
   * Terminal session ID for execution (default: 1)
   * @minimum 1
   * @maximum 65535
   */
  terminal_id?: number /* min: 1, max: 65535 */;
  /** X11 DISPLAY number (defaults to terminal_id) */
  display?: string;
  /** Origin identifier for observability propagation */
  origin?: string;
  format?: OutputFormat;
  /** Force command-only output. hoody-run never executes, so this is always in effect. */
  dry_run?: boolean;
  print_curl?: PrintCurlMode;
  /**
   * Maximum candidates to return (default: 25)
   * @minimum 1
   * @maximum 100
   */
  limit?: number /* min: 1, max: 100 */;
}

/**
 * Response from the search endpoint containing a set ID for race-free selection and the ranked list of candidates.
 */
export interface SearchResponse {
  statusCode: number;
  message: string;
  data: { set_id: string; candidates: Candidate[] };
}

/**
 * Response from run endpoints. The shape varies by status:
- resolved: set_id + candidates (no single candidate selected)
- dry-run: set_id + selected + shell_command (hoody-run never executes)
- printed-curl: set_id + selected + curl command
- error: set_id + error message
 */
export interface RunResponse {
  statusCode: number;
  message: string;
  data: { status: RunStatus; set_id?: string; candidates?: Candidate[]; selected?: Candidate; shell_command?: string; curl?: string; error?: string; handoff?: RunHandoff; warnings?: WarningEntry[] };
}

/**
 * Standard JSON error payload for request validation, lookup failures, and upstream/service issues.
 */
export interface ApiError {
  /** Human-readable error message */
  error: string;
  /** HTTP status code associated with the error */
  code: number;
}

/**
 * Specific source implementation type. Determines how the source resolves and syncs candidates.
 */
export type SourceType = "nix-pkgs" | "nix-flake" | "pkgx" | "app-image-pinned" | "app-image-git-hub-releases" | "app-image-catalog" | "oci-local-images" | "manifest-registry" | "manifest-remote-index" | "system-path" | "trusted-list-file";

/**
 * Pin configuration for a source, including URL and optional integrity verification fields.
 */
export interface SourcePin {
  /** Pinned URL for the source */
  url: string;
  /** SHA-256 hash for integrity verification */
  sha256?: string;
  /** Ed25519 public key of the source author (base64) */
  author_pubkey_ed25519?: string;
  /** Ed25519 signature for provenance verification (base64) */
  sig_ed25519?: string;
}

/**
 * Default selector values applied when a profile is active and the request does not explicitly set these fields.
 */
export interface ProfileDefaults {
  os?: Os;
  kind?: AppKind;
  /** Default source filter */
  source?: SourceKind[];
  pick?: PickMode;
  /**
   * Default terminal session ID
   * @minimum 1
   * @maximum 65535
   */
  terminal_id?: number /* min: 1, max: 65535 */;
  /** Default X11 DISPLAY number */
  display?: string;
  /**
   * Default maximum candidates to return
   * @minimum 1
   * @maximum 100
   */
  limit?: number /* min: 1, max: 100 */;
}

/**
 * How a profile interacts with the global source list:
- inherit: start from global sources, apply overrides
- allowlist: disable all sources first, then enable only those listed in the profile's sources array
 */
export type ProfileSourceMode = "inherit" | "allowlist";

/**
 * Per-source override within a profile.
 */
export interface ProfileSourceOverride {
  /** ID of the source to override */
  source_id: string;
  /** Override enabled state */
  enabled?: boolean;
  /** Override priority */
  priority?: number;
}

export interface PolicyConfig {
  require_verified?: boolean;
  require_integrity?: boolean;
  deny_providers?: SourceKind[];
  deny_source_ids?: string[];
}

/**
 * Partial selector template used by saved recipes and recipe override requests.
 */
export interface SelectorTemplate {
  app?: string;
  os?: Os;
  kind?: AppKind;
  source?: SourceKind[];
  arch?: Arch;
  tags?: string[];
  profile?: string;
  channel?: string;
  version?: string;
  variant?: string;
  publisher?: string;
  repo?: string;
  release?: string;
  asset?: string;
  pick?: PickMode;
  /** @minimum 0 */
  pick_index?: number /* min: 0 */;
  candidate_id?: string;
  set_id?: string;
  /**
   * @minimum 1
   * @maximum 65535
   */
  terminal_id?: number /* min: 1, max: 65535 */;
  display?: string;
  origin?: string;
  format?: OutputFormat;
  dry_run?: boolean;
  print_curl?: PrintCurlMode;
  /**
   * @minimum 1
   * @maximum 100
   */
  limit?: number /* min: 1, max: 100 */;
}

/**
 * Job execution mode
 */
export type ExecutionMode = "sync" | "async";

/**
 * Response mode
 */
export type ResponseMode = "transparent" | "json";

/**
 * Filesystem confinement. Applied as bubblewrap bind mounts inside the program's own user and mount namespace, so the program sees a different tree from the rest of the container. Independently of these fields, every sandboxed program sees an empty `/run/user` in place of the real one, so it cannot reach its account's systemd user manager or session bus; a sandboxed program whose `directory` is under `/run/user` is rejected with 400. Unknown keys are rejected with 400. Every field of this object, and the object itself, accepts an explicit `null`, which is treated exactly as if the field had been omitted (only the top-level `sandbox` key of an edit distinguishes `null` from omission).
 */
export interface SandboxFilesystem {
  /** Bind `/` read-only (`--ro-bind / /`). Every path on the root mount outside `writable` answers EROFS; `/dev`, `/proc`, a private `/tmp` and `/var/tmp`, and the hidden tmpfs mounts are their own mounts, and ordinary account permissions still apply. `/sys` is bound read-only for every sandboxed program regardless of this flag, so the program cannot edit its own cgroup limits. */
  read_only_root?: boolean | null;
  /** Absolute directories bound read-write inside the read-only root (`--bind-fd <fd> p`: the stage that execs bubblewrap opens each directory `O_PATH|O_DIRECTORY|O_NOFOLLOW` while still root, checks the descriptor's device and inode against the identity approved at launch, and passes the descriptor itself as the mount source, so what is mounted writable is the approved object). Needs a bubblewrap with `--bind-fd` (0.12.0 measured). Each must already exist and is canonicalized. `read_only_root` must be true — `writable` on its own is a 400, not a restriction. A path may neither equal, contain, nor be contained by a protected root: the configured storage and supervisord config trees, the log base directory, `/etc`, `/run`, `/var/run`, `/hoody/plugins`, `/proc`, `/sys`, `/dev`, `/boot`, and the daemon executable's directory. `/hoody` and `/hoody/storage` are therefore refused because they contain the daemon's own tree; `/hoody/storage/apps/<name>` is accepted. At launch the wrapper's outer stage canonicalizes each path, records its `(st_dev, st_ino)`, and compares those against a fresh stat immediately before the sandbox is spawned; a path that changed identity, or is no longer a directory, is refused. The comparison is between those two launch-time observations, not against the identity the API saw when the policy was stored. The destination of the mount is still resolved by pathname, so an actor who controls the path or a mutable ancestor can move where the approved object appears, never what it is. */
  writable?: string[] | null;
  /** Absolute directories replaced by an empty, unreadable tmpfs (`--perms 0000 --tmpfs p`). Same both-direction overlap rule as `writable`, and additionally may not overlap `/usr`, `/bin`, `/sbin`, `/lib*`, `/hoody`, `/hoody/storage`, the program's own `directory`, or any `writable` entry. */
  hidden?: string[] | null;
}

/**
 * Network confinement. Outbound and bind restrictions are enforced per process by Landlock; inbound restrictions are enforced by one nftables table shared by every sandboxed program. Unknown keys are rejected with 400. Every field of this object, and the object itself, accepts an explicit `null`, which is treated exactly as if the field had been omitted (only the top-level `sandbox` key of an edit distinguishes `null` from omission).
 */
export interface SandboxNetwork {
  /** `full` (default): no Landlock restriction on binding or connecting. Ingress settings still apply, so a `full` program can still carry an allowlist and a rate limit. `restricted`: Landlock (ABI 4 or higher; ABI 9 measured) confines TCP bind and connect to `bind_ports` and `connect_ports`. Landlock is TCP-only, so UDP, ICMP and raw sockets are unaffected by this mode. So that the port lists hold, a `restricted` program also cannot create MPTCP or SMC sockets, cannot use io_uring and cannot send with `MSG_FASTOPEN`: an MPTCP request answers `EPROTONOSUPPORT`, `io_uring_setup` answers `ENOSYS` and a Fast Open send answers `EOPNOTSUPP`, so software that falls back to plain TCP, to epoll or to connect-then-send keeps working, and a program that requires io_uring does not run in this mode. `none`: the program runs in an empty network namespace (`--unshare-net`), which closes IP and abstract unix sockets but NOT a unix socket reachable by filesystem path; `port_range`, `ready_port`, any non-null `bind_ports` (an empty list included), a non-empty `connect_ports` or `ingress_allow_from`, and any `ingress_rate_limit` are then rejected with 400; empty `connect_ports` / `ingress_allow_from` lists and `ingress_allow_platform` are accepted and inert. */
  mode?: "full" | "restricted" | "none" | null;
  /** TCP ports the program may bind (Landlock `BIND_TCP`; connecting is a separate access bit governed by `connect_ports`, and neither covers a socket that begins listening without binding). Overlapping and adjacent items are merged into disjoint ranges. Defaults to the union of `port_range` and `ready_port` (whichever are set), else empty; it is required for `mode: restricted` when neither is set, and must cover `port_range` and `ready_port` when those are set. This is also the listening set used for ingress rules and for port ownership, for an EFFECTIVE block only (a block that restricts nothing claims no ports): a port is reserved container-wide across every local address, so a create or edit whose listening set overlaps another program's declared ports, a still-draining policy, the Hoody Kit ports or the daemon's own effective port is rejected with 400. Other programs' declared ports and installed firewall records are checked whenever a sandbox is involved on either side; two programs without a sandbox block keep the pre-sandbox rule (overlapping `port_range` values are refused, `ready_port` is not checked). Enabling a program re-checks ownership on the view it will have once enabled, whether or not it carries a sandbox block, so a program disabled while a sandboxed neighbour took its port is refused rather than brought back onto it. The Hoody Kit and daemon ports are reserved against sandboxed listening sets. Ports that an unsandboxed command opens without declaring them are unknowable and are not protected. */
  bind_ports?: (number /* min: 1, max: 65535 */ | string)[] | null;
  /** TCP ports the program may connect to (Landlock `CONNECT_TCP`). Same item grammar as `bind_ports`. Valid only with `mode: restricted`; a non-empty list with any other mode is a 400. */
  connect_ports?: (number /* min: 1, max: 65535 */ | string)[] | null;
  /**
   * Source networks allowed to open NEW connections to the listening set on `eth0`. Enforcement is IPv4 TCP on eth0. Rules match by destination PORT only, never by destination address, so they hold whether or not the daemon's localhost DNAT rule is installed. Established and related connections return before the allowlist is consulted, so tightening this field filters new connections and never cuts live ones. Because matching is per port, an undeclared service listening on the same port on another local address is filtered too. Requires a non-empty listening set. Maximum 64 entries, each a strict dotted-quad `a.b.c.d/n`.
   * @maxItems 64
   */
  ingress_allow_from?: string[] | null;
  /** Accept traffic from `127.0.0.0/8` and from the eth0 default gateway before the rate meter and the allowlist are consulted, so container-local callers and hairpinned requests are neither filtered nor throttled. The exemption matches the packet's source address, not the caller's identity. edge proxy forwards ordinary public traffic transparently, with the client's own address as the source, so that traffic meets the allowlist and the meter like any other source; what the exemption covers is traffic whose source is loopback or the gateway, such as container-local callers and hairpinned requests. Default true. On its own it restricts nothing: a sandbox block whose only content is `ingress_allow_platform` normalizes to no sandbox at all and the program is rendered exactly as it is today. */
  ingress_allow_platform?: boolean | null;
  /**
   * Per-source-address budget for new connections, `"N/s"` or `"N/m"` with N between 1 and 100000. Implemented as an nftables dynamic set named `hd_<id>_<rev12>_rate` (60 s timeout, 65535 entries) evaluated after the platform exception and BEFORE the allowlist; a policy with only a rate limit has no terminal drop, so sources within budget pass. Only new connections are metered: SYN is matched under the `fin|syn|rst|ack` mask so ECN-capable SYNs count. Two documented consequences — budgets reset whenever the table is regenerated, which any admission that changes the table, any retirement, any finalize or rollback of an ingress policy, and every daemon start and reset causes; and once the set is full new sources are untracked, so the rate limit fails open while the allowlist keeps applying.
   * @pattern ^\d+/[sm]$
   */
  ingress_rate_limit?: string | null;
}

/**
 * Process limits, applied by three different mechanisms: `max_memory` and `max_pids` by systemd on the transient scope that owns the program's cgroup, `max_open_files` as an in-process resource limit set just before the program is executed, and `private_tmp` as bubblewrap mounts. The program sees `/sys` read-only and cannot raise the cgroup limits. Unknown keys are rejected with 400. Every field of this object, and the object itself, accepts an explicit `null`, which is treated exactly as if the field had been omitted (only the top-level `sandbox` key of an edit distinguishes `null` from omission).
 */
export interface SandboxProcess {
  /**
   * Memory ceiling, from 16M to 64G, written as `<n>[KMG]` in binary units or as a plain decimal byte count in the same range. A bare decimal is a byte count (`"536870912"` and `"512M"` are the same limit). Written to the scope as `MemoryMax=` in bytes together with `MemorySwapMax=0` and `OOMPolicy=continue`. The swap cap is what makes the limit enforceable: on a container with swap, `MemoryMax` alone lets a process go past the cap by swapping. With `OOMPolicy=continue` only the offending process is killed by the kernel; when that is the program itself it reaches supervisord as exit 137 and the wrapper then tears down the rest of the scope.
   * @pattern ^\d+[KMG]?$
   */
  max_memory?: string | null;
  /**
   * `TasksMax=` on the scope, from 4 to 65536. The count includes the two wrapper helpers (the scope payload and bubblewrap), so budget at least 2 above the program's own process and thread count.
   * @minimum 4
   * @maximum 65536
   */
  max_pids?: number /* min: 4, max: 65536 */ | null;
  /**
   * `RLIMIT_NOFILE`, soft and hard, from 8 to 1048576. Set last, inside the sandbox, immediately before the program is exec'd, so the descriptors the wrapper chain needs are not charged against it.
   * @minimum 8
   * @maximum 1048576
   */
  max_open_files?: number /* min: 8, max: 1048576 */ | null;
  /** Give the program its own empty `/tmp` and `/var/tmp` (`--tmpfs`), invisible to the rest of the container. Rejected with 400 when a `filesystem.writable` entry equals, contains or is contained by `/tmp` or `/var/tmp`: the private mounts are applied first, so a writable bind over them would expose the container's shared directory. Also rejected when the program's `directory` lies strictly below `/tmp` or `/var/tmp`, or when the daemon itself is installed below either: the private mounts would hide them and the launch could not reach the program. */
  private_tmp?: boolean | null;
}

/**
 * Represents a running instance of a port-range program. Each instance is an actual process running on a specific port.
 */
export interface ProgramInstance {
  /** Port number this instance is running on */
  port: number;
  /** Supervisord process name (format: programname_port) */
  instance_name: string;
  /** Current runtime status of this instance. Lowercased supervisord state name; `stopped` is returned when supervisorctl cannot be executed at all; `unknown` when supervisord is unreachable or its output cannot be parsed. */
  status: "running" | "stopped" | "starting" | "stopping" | "backoff" | "exited" | "fatal" | "unknown";
  /** Process ID when running; omitted otherwise */
  pid?: number;
  /** Uptime as supervisord renders it — "H:MM:SS", or "N day(s), H:MM:SS" once the process has been up for more than a day. Omitted when not running. */
  uptime?: string;
  /** Resource stats for this instance's process tree. Only present when include_stats=true and the instance is running. */
  stats?: ProgramStats;
}

/**
 * Flexible value type used for defaults metadata
 */
export type AnyValue = string | number | boolean | unknown[] | Record<string, unknown> | null;

/**
 * What changed. Writes, including writes through a shared memory mapping,
are `modified`; opening a file for writing and closing it unchanged may
also report `modified`. Opening, reading or listing a file or directory
(and a read-only close) is not reported. `modified` and `metadata` are
reported only for a path that exists when the event is processed, so a
write or close through a descriptor that outlives the file's name is not
reported. A change may be reported as only the `removed` or `renamed`
that follows it, when the file, or a directory above it, is removed or
renamed away before the change is processed. `overflow` means events were
lost (backend queue overflow or stream saturation); the service then rescans
the watched paths, but does not replay the lost changes. `other` is
reserved for a backend event that fits no other kind; the Linux backend
produces none.
 */
export type WatchEventKind = "created" | "modified" | "removed" | "renamed" | "metadata" | "overflow" | "other";

/**
 * Status of a run request:
- resolved: candidates found but no single candidate selected (no pick or pick=ask)
- dry-run: candidate selected and its exact shell command returned (hoody-run never executes)
- printed-curl: equivalent curl command generated (print_curl set)
- error: an error occurred during resolution
 */
export type RunStatus = "resolved" | "dry-run" | "printed-curl" | "error";

/**
 * A standardized runnable application candidate produced by a source provider. Contains all information needed to identify, rank, and return exact shell commands for execution.
 */
export interface Candidate {
  /** Stable hash of canonical candidate payload, unique within a candidate set */
  candidate_id: string;
  /** Human-readable display title */
  title: string;
  /** Brief description of the candidate */
  description: string;
  /** Whether the candidate is a GUI or CLI application. `any` means the source does not classify it; only sources with an explicit kind (e.g. manifest registries) emit gui/cli. */
  kind: AppKind;
  /** Provider-reported version string */
  version?: string;
  /** Provider or project homepage URL */
  homepage?: string;
  /** Tags for categorization and filtering */
  tags?: string[];
  provider: SourceKind;
  /** ID of the source that produced this candidate */
  source_id: string;
  /** Ranking score (higher is better) */
  score: number;
  /** Human-readable reasons why this candidate matched or ranked highly */
  reasons?: string[];
  integrity?: Integrity;
  run_plan: RunPlan;
  execution_plan?: ExecutionPlan;
  /** Whether the candidate was verified by a trusted source or integrity check */
  verified?: boolean;
  provenance?: CandidateProvenance;
  /** Exact shell command after applying run_plan.env and run_plan.cwd wrapping */
  shell_command?: string;
  /** Path-only reference URL (no domain) for HTML links */
  href_path?: string;
}

/**
 * Where the selected app will appear once the returned command runs.
 */
export interface RunHandoff {
  state: HandoffState;
  terminal_id: number;
  display: string;
  /** Preview display page URL — where the app will appear (present only when state=preview) */
  preview_display_url?: string;
  /** Preview terminal viewer URL — where the app will appear (present only when state=preview) */
  preview_terminal_url?: string;
}

export interface WarningEntry {
  code: string;
  message: string;
}

/**
 * Target app runtime OS (not the host OS). Determines which candidates are eligible.
 */
export type Os = "linux" | "windows" | "any";

/**
 * Target CPU architecture for filtering candidates.
 */
export type Arch = "amd64" | "arm64" | "any";

/**
 * Candidate selection mode:
- ask: return candidate list without selecting (default)
- first: automatically select the highest-ranked candidate
- index: select by 0-based index (requires pick_index)
- id: select by candidate_id (requires candidate_id)
 */
export type PickMode = "ask" | "first" | "index" | "id";

/**
 * Output format override. When set, takes precedence over Accept header content negotiation.
 */
export type OutputFormat = "json" | "html";

/**
 * Curl command generation mode:
- hoody-run: generate curl for the hoody-run /api/v1/run/resolve endpoint
 */
export type PrintCurlMode = "hoody-run";

/**
 * Aggregated resource stats for a program including its full process tree (root process + all child/descendant processes). Read from /proc filesystem.
 */
export interface ProgramStats {
  /** Root process ID (the PID supervisord manages) */
  pid: number;
  /** ISO 8601 timestamp of when the process started */
  started_at: string;
  /** Total CPU usage percentage across all processes in the tree (can exceed 100% on multi-core). This is a lifetime average — total CPU time divided by the process's age — not instantaneous usage. */
  cpu_percent: number;
  /** Total Resident Set Size in bytes across all processes in the tree */
  memory_rss_bytes: number;
  /** Number of processes in the tree (root + children) */
  process_count: number;
  /** Per-process breakdown of the process tree */
  processes: ProcessInfo[];
}

/**
 * Application kind filter - gui for graphical apps, cli for terminal apps, any for both.
 */
export type AppKind = "gui" | "cli" | "any";

/**
 * Package source provider kind. Used for filtering candidates by source and as the provider field on candidates.
 */
export type SourceKind = "nix" | "pkgx" | "appimage" | "oci" | "registry" | "system" | "any";

/**
 * Optional integrity and provenance information for a candidate, including download URL, hash, and optional Ed25519 signature.
 */
export interface Integrity {
  /** Download or source URL */
  url: string;
  /** SHA-256 hash of the artifact */
  sha256?: string;
  /** Ed25519 public key of the manifest author (base64) */
  author_pubkey_ed25519?: string;
  /** Ed25519 signature of the manifest content (base64) */
  sig_ed25519?: string;
}

/**
 * Execution plan for a candidate. Contains the base shell command with optional environment variables and working directory metadata.
 */
export interface RunPlan {
  /** Complete shell command (no placeholders) */
  command: string;
  /** Environment variables to set before command execution */
  env?: Record<string, string>;
  /** Working directory for command execution */
  cwd?: string;
}

export interface ExecutionPlan {
  mode?: ExecutionMode2;
  shell?: string;
  shell_command?: string;
  argv?: string[];
  env?: Record<string, string>;
  cwd?: string;
  side_effect_hints?: SideEffectHint[];
}

export interface CandidateProvenance {
  match_kind?: string;
  matched_value?: string;
  match_evidence?: MatchEvidence[];
  score_components?: ScoreComponent[];
  verification?: VerificationEvidence;
  provider_notes?: string[];
}

/**
 * Liveness of the handoff. hoody-run never executes, so the only state is:
- preview: nothing executed; preview_* URLs show where the app WILL appear
 */
export type HandoffState = "preview";

/**
 * Resource stats for a single process in the process tree
 */
export interface ProcessInfo {
  /** Process ID */
  pid: number;
  /** Command line of the process */
  command: string;
  /** CPU usage percentage (can exceed 100% on multi-core systems). This is a lifetime average — total CPU time divided by the process's age — not instantaneous usage. */
  cpu_percent: number;
  /** Resident Set Size in bytes */
  memory_rss_bytes: number;
}

/**
 * Structured execution plan mode.
 */
export type ExecutionMode2 = "shell-inline" | "argv";

export interface SideEffectHint {
  code: string;
  description: string;
}

export interface MatchEvidence {
  field: string;
  kind: string;
  value: string;
}

export interface ScoreComponent {
  label: string;
  delta: number;
  detail?: string;
}

export interface VerificationEvidence {
  verified: boolean;
  status?: string;
  note?: string;
}

/** browser's `Error` schema, whatever order the specs are merged in (same type as `Error`). */
export type BrowserError = Error;

/** code's `Error` schema, whatever order the specs are merged in (same type as `Error2`). */
export type CodeError = Error2;

/** daemon's `Error` schema, whatever order the specs are merged in (same type as `Error3`). */
export type DaemonError = Error3;

/** display's `Error` schema, whatever order the specs are merged in (same type as `Error4`). */
export type DisplayError = Error4;

/** exec's `Error` schema, whatever order the specs are merged in (same type as `Error5`). */
export type ExecError = Error5;

/** notifications's `Error` schema, whatever order the specs are merged in (same type as `Error6`). */
export type NotificationsError = Error6;

/** bot's `Error` schema, whatever order the specs are merged in (same type as `Error7`). */
export type BotError = Error7;

/** curl's `ExecutionMode` schema, whatever order the specs are merged in (same type as `ExecutionMode`). */
export type CurlExecutionMode = ExecutionMode;

