/**
 * The event payloads of sqlite_streamKvChanges's stream, keyed by message title
 * (the message name when it has none), from the operation's x-async-api messages.
 */
export interface SqliteKvStreamChangesEvents {
  /** First frame. Its id is the cursor the stream continues from (the supplied one, or the current position). */
  "ready": { cursor: string; oldest_cursor: string };
  /** One change of a matching key. Its id is the event cursor. */
  "change": { content_type?: string; cursor: string; etag?: string; expire_at: number | null; key: string; op: "set" | "ttl" | "delete" | "expire"; seq: number; table: string; ts: number; value?: unknown; value_base64?: string; value_omitted?: "superseded" | "expired" | "too_large" };
  /** Position scanned so far (every 15 s and after 1000 skipped changes). Its id is a valid resume point; nothing to apply. */
  "checkpoint": { cursor: string };
  /** The stream cannot continue from its position: re-read the state and start from a new cursor. The server closes the stream after it. */
  "reset": { reason: "cursor_expired" | "database_replaced" | "table_changed" | "future_cursor" };
  /** The server closes the stream. Reconnect with the last id for shutdown and max_lifetime; database_deleted is final. */
  "end": { reason: "database_deleted" | "shutdown" | "max_lifetime" };
}

/**
 * The event payloads of terminal_connectTerminalWebSocket's stream, keyed by message title
 * (the message name when it has none), from the operation's x-async-api messages.
 */
export interface TerminalSessionsConnectEvents {
  /** Binary message containing terminal output from PTY process. First byte is '0' (OUTPUT command), followed by raw ANSI-formatted terminal data. May include ANSI escape sequences for colors, cursor positioning, etc. Broadcast to all clients sharing the terminal session. */
  "Terminal Output": { command: "0"; data: string };
  /** Text message to update the browser window title. First byte is '1' (SET_WINDOW_TITLE command), followed by title text. Sent during initial connection sequence. Format is "command (hostname)". */
  "Set Window Title": { command: "1"; title: string };
  /** JSON message containing client configuration preferences. First byte is '2' (SET_PREFERENCES command), followed by JSON object. Sent during initial connection sequence. Preferences may include theme, font settings, keybindings, etc. */
  "Set Client Preferences": { command: "2"; preferences: { fontSize?: number; theme?: string; fontFamily?: string } };
  /** Text message assigning terminal session ID to this client. First byte is '3' (SET_TERMINAL_ID command), followed by terminal_id string. Sent during initial connection sequence. Allows multiple clients to identify shared sessions. */
  "Set Terminal ID": { command: "3"; terminal_id: string };
  /** Text message indicating the type of shell running in the terminal. First byte is '4' (SET_SHELL_TYPE command), followed by shell name string. Sent during initial connection sequence. Used for UI indicators and syntax highlighting hints. */
  "Set Shell Type": { command: "4"; shell_type: "bash" | "zsh" | "fish" | "sh" | "ssh" | "tmux" };
}

