  /** Snapshot of background tasks. */
  "event.tasks_snapshot": { tasks?: Record<string, unknown>[]; rev?: number };
  /** Reasoning/thinking stream chunk. */
  "event.thinking_chunk": { text: string; helper_id?: string; parent_tool_call_id?: string };
  /** Thinking stall warning. */
  "event.thinking_stall": Record<string, unknown>;
  /** TODO list updated. */
  "event.todo_list_updated": Record<string, unknown>;
  /** Tool invocation. */
  "event.tool_call": { tool_id: string; name: string; arguments?: Record<string, unknown>; summary: string; reason?: string; timeout_sec?: number; reason_not_read_file?: string; reason_not_edit_file?: string; reason_not_glob_files?: string; reason_to_increase_timeout?: string; helper_id?: string; parent_tool_call_id?: string };
