  "event.workflow_step_done": { step_id: string; step_idx: number; total: number; success: boolean; timed_out?: boolean; display?: string; command?: string; bash_output?: string; model?: string; input_tokens?: number; output_tokens?: number; cache_creation_tokens?: number; cache_read_tokens?: number; cost?: number; tool_stats?: { name: string; calls: number; summary: string }[]; duration_ms?: number; depth?: number; replayed?: boolean };
